#!/usr/bin/env bash
set -euo pipefail
WORK="/tmp/jrx-p1-etl"
LOG_DIR="${NYS_OPS_LOG_DIR:-/var/log/nys-ops}"
PY="${CASE_API_PYTHON:-/home/ubuntu/scripts/case_api/.venv/bin/python3}"
PIP="${CASE_API_PIP:-${PY%python3}pip}"
LOOKUP="${CASE_API_LOOKUP_DIR:-/home/ubuntu/scripts/case_api/_build/case_lookup_full/current}"
# DuckDB fetchdf() requires numpy+pandas in the case_api venv (P1 crash 2026-09-19/20).
for pkg in 'numpy>=1.24' 'pandas>=2.0'; do
  mod="${pkg%%[>=]*}"
  if ! "$PY" -c "import ${mod}" >/dev/null 2>&1; then
    echo "${mod^^}_INSTALL start pip=$PIP"
    "$PIP" install -q "$pkg" || "$PIP" install "$pkg"
  fi
  echo "${mod^^}_VERSION=$("$PY" -c "import ${mod}; print(${mod}.__version__)" 2>/dev/null || echo missing)"
done
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
LOG="$LOG_DIR/p1-etl-${STAMP}.log"
mkdir -p "$LOG_DIR" "$WORK"
if pgrep -f "$WORK/etl.py" >/dev/null 2>&1; then echo "SKIPPED: running"; pgrep -af etl.py; exit 0; fi
rm -f /opt/nyv/api/.p1_rds_helper.mjs "$WORK"/payload-*.json
echo "" | base64 -d > "$WORK/etl.py"
echo "" | base64 -d > "$WORK/view-ddl.sql"
cat >"$WORK/staging-ddl.sql" <<'SQL'
BEGIN;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS diary_no text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS petitioner_address text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS respondent_address text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS petitioner_phone text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS respondent_phone text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS petitioner_email text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS respondent_email text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS petitioner_father_name text;
ALTER TABLE cases_search_staging ADD COLUMN IF NOT EXISTS respondent_father_name text;
CREATE INDEX IF NOT EXISTS idx_css_diary_no ON cases_search_staging (diary_no) WHERE diary_no IS NOT NULL AND btrim(diary_no) <> '';
COMMIT;
SQL
NOW_YEAR="$(date -u +%Y)"
nohup env CASE_API_LOOKUP_DIR="$LOOKUP" P1_DDL_PATH="$WORK/staging-ddl.sql" P1_VIEW_DDL_PATH="$WORK/view-ddl.sql" CORPUS_END_YEAR="${CORPUS_END_YEAR:-$NOW_YEAR}" CORPUS_START_YEAR="${CORPUS_START_YEAR:-$((NOW_YEAR-1))}" RDS_STATEMENT_TIMEOUT_MS="${RDS_STATEMENT_TIMEOUT_MS:-600000}" P1_ETL_BATCH_SIZE="${P1_ETL_BATCH_SIZE:-500}" NYS_API_DIR="/opt/nyv/api" "$PY" "$WORK/etl.py" >>"$LOG" 2>&1 &
echo "P1_ETL_STARTED pid=$! log=$LOG"
sleep 3
pgrep -af "$WORK/etl.py" || true
